window.MOTIF_CATALOG_CHUNKS[94]={"cards":[{"id":"MEJE-KW-009520","row_version":1,"title":"열린 무덤에 빠지다","original":"Falling into an Open Grave","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 미리 파 놓은 무덤에 우연히 빠져 공포나 희극적 상황이 생긴다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-009520/index.html"},{"id":"MEJE-KW-009521","row_version":1,"title":"품에 떨어진 만남","original":"Falling into His Arms","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"한 인물이 넘어지거나 떨어지는 순간 다른 인물이 받아 주며 우연한 만남을 낭만적인 장면으로 만든다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-009521/index.html"},{"id":"MEJE-KW-009522","row_version":2,"title":"감옥에 떨어진 범인","original":"Falling into Jail","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"적대자가 날아가듯 튕겨 나간 끝에 우연히 감옥 안으로 들어가 체포되는 만화적 장면이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-009522/index.html"},{"id":"MEJE-KW-009523","row_version":1,"title":"초보자의 조종석","original":"Falling into the Cockpit","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"조종 경험이 부족한 인물이 비상 상황에서 고성능 탈것에 올라 즉석에서 운용해야 한다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-009523/index.html"},{"id":"MEJE-KW-009524","row_version":1,"title":"추락으로 시작되는 모험","original":"Falling into the Plot","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"인물이 아래로 떨어지는 사건을 계기로 낯선 세계나 새로운 이야기의 중심에 들어선다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-009524/index.html"},{"id":"MEJE-KW-009525","row_version":2,"title":"쓰러지는 나무의 위협","original":"Falling Tree of Doom","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"나무가 무너지며 지나가는 인물을 위협하거나 추격 장면의 장애물이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-009525/index.html"},{"id":"MEJE-KW-009526","row_version":1,"title":"무너지는 카드집","original":"Fall of the House of Cards","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"공들여 쌓아 올린 카드집이 완성 직전 작은 방해로 무너져 허탈감이나 웃음을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-009526/index.html"},{"id":"MEJE-KW-009527","row_version":2,"title":"실패한 방공호","original":"Fallout Shelter Fail","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"위기에서 안전을 약속하던 피난 시설이 실제로 필요해진 순간 결함이나 준비 부족을 드러낸다. 안전하다고 여겨진 장소의 결함이 드러나는 구조는 겉만 낙원인 세계과 통한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-009527/index.html"},{"id":"MEJE-KW-009528","row_version":3,"title":"학대 허위 고발","original":"False Abuse Accusation","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"작품 속에서 학대가 일어나지 않았는데도 특정 인물이 가해자로 지목되어 갈등이 생기는 서사 장치다. 고발을 둘러싼 허위 사실이 작품 안에서 확인되는 서사 가운데 구체적인 유형이 성폭력 허위 고발이다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-009528/index.html"},{"id":"MEJE-KW-009529","row_version":1,"title":"외도 허위 고발","original":"False Adultery Accusation","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"한 인물이 실제로 외도하지 않았는데도 의심이나 거짓 고발로 관계의 신뢰가 흔들린다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-009529/index.html"},{"id":"MEJE-KW-009530","row_version":1,"title":"가짜 카메라 효과","original":"False Camera Effects","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"그림이나 애니메이션이 렌즈 반사, 초점 흐림 같은 촬영 장비의 흔적을 의도적으로 재현한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-009530/index.html"},{"id":"MEJE-KW-009531","row_version":2,"title":"잘못된 인과관계","original":"False Cause","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"두 사건이 함께 일어났다는 이유만으로 하나가 다른 하나를 일으켰다고 판단하는 논리적 오류다. 주장의 허점을 만드는 또 다른 논리적 오류로 가짜 양자택일이 있다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-009531/index.html"},{"id":"MEJE-KW-009532","row_version":2,"title":"거짓 자백","original":"False Confession","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"인물이 하지 않은 잘못을 자신이 저질렀다고 말해 수사나 다른 인물의 판단을 바꾼다. 실제 책임을 지지 않는 사람이 범인으로 굳어질 때 희생양으로 몰린 사람이 되기도 한다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-009532/index.html"},{"id":"MEJE-KW-009533","row_version":2,"title":"실제 작업과 어긋난 크레딧","original":"False Credit","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작업에 기여하지 않은 사람이 계약이나 관행 때문에 크레딧에 이름을 올리거나, 실제 기여자가 가려지는 제작 관행.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-009533/index.html"},{"id":"MEJE-KW-009534","row_version":1,"title":"가짜 시련","original":"False Crucible","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"인물의 성품이나 선택을 시험하려고 누군가가 꾸민 시련. 실제 위험처럼 보이던 상황의 목적이 시험이었다는 사실이 드러난다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-009534/index.html"},{"id":"MEJE-KW-009535","row_version":1,"title":"가짜 양자택일","original":"False Dichotomy","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"더 많은 선택지가 있는데도 둘 중 하나만 고를 수 있는 것처럼 제시하는 논리적 오류다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-009535/index.html"},{"id":"MEJE-KW-009536","row_version":1,"title":"거짓 경보인 줄 알게 하기","original":"False False Alarm","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"침입자가 경보를 일부러 반복 작동시켜 경비가 이를 오작동으로 여기게 만들거나, 진짜 경보를 미끼로 삼아 대응을 흐트러뜨리는 서사적 수법.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-009536/index.html"},{"id":"MEJE-KW-009537","row_version":2,"title":"타인에게 뒤집어씌우는 작전","original":"False Flag Operation","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"한 세력이 자신의 행동을 다른 세력이 저지른 것처럼 보이게 해 갈등과 책임의 방향을 바꾼다. 행동의 책임을 다른 대상에게 돌리면 그 대상은 희생양으로 몰린 사람이 된다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-009537/index.html"},{"id":"MEJE-KW-009538","row_version":2,"title":"호감 가장 전략","original":"False Flirting Stratagem","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"인물이 정보를 얻거나 원하는 반응을 끌어내기 위해 상대에게 연애 감정이 있는 척한다. 상대와의 친밀함을 수단으로 삼는다는 점에서 가짜 친구과 가깝다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-009538/index.html"},{"id":"MEJE-KW-009539","row_version":1,"title":"가짜 친구","original":"False Friend","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"친구인 척 다가온 인물이 실제로는 상대를 이용하거나 배신할 목적을 품고 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-009539/index.html"},{"id":"MEJE-KW-009540","row_version":2,"title":"억울한 죄수인 척하는 악당","original":"False Innocence Trick","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"정당한 이유로 갇힌 악당이 무고한 죄수처럼 행동해 영웅의 동정심을 얻고 풀려나는 전개. 위험한 인물이 신뢰를 얻으려고 겉모습을 바꾸는 방식은 개심한 척하는 악역에도 나타난다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-009540/index.html"},{"id":"MEJE-KW-009541","row_version":1,"title":"정확성 과장 홍보","original":"Falsely Advertised Accuracy","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품이 사실 고증의 정확성을 내세우지만 내용에서 뚜렷한 오류나 각색이 드러나는 경우다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-009541/index.html"},{"id":"MEJE-KW-009542","row_version":1,"title":"개심한 척하는 악역","original":"Falsely Reformed Villain","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"악역이 마음을 고쳐먹었다고 주장하며 신뢰를 되찾지만 실제 목적은 따로 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-009542/index.html"},{"id":"MEJE-KW-009543","row_version":2,"title":"거짓 예언자","original":"False Prophet","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"대중을 구원하거나 더 나은 미래를 만들겠다고 설파하지만, 실제로는 사적인 이익을 위해 추종자를 이용하는 인물이다. 자신의 목적을 감추기 위해 믿음을 내세우는 행동은 신앙 가장과 이어진다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-009543/index.html"},{"id":"MEJE-KW-009544","row_version":2,"title":"성폭력 허위 고발","original":"False Rape Accusation","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"작품 속에서 성폭력이 일어나지 않았는데도 특정 인물이 가해자로 지목되는 서사 장치다. 현실의 신고나 피해에 대한 일반화로 읽히지 않도록 작품 안의 사실관계가 확인된 경우로 한정한다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-009544/index.html"},{"id":"MEJE-KW-009545","row_version":1,"title":"말장난식 거짓 안심","original":"False Reassurance","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"문장 자체는 사실이지만 듣는 사람이 다른 뜻으로 받아들이도록 말해 안심시키거나 진상을 숨기는 대화 방식이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-009545/index.html"},{"id":"MEJE-KW-009546","row_version":2,"title":"가짜 러시안룰렛 협박","original":"False Roulette","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"인물이 위험한 도박을 벌이는 것처럼 연출해 상대를 압박하지만, 장면의 핵심은 그 위험을 둘러싼 속임수에 있다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-009546/index.html"},{"id":"MEJE-KW-009547","row_version":1,"title":"운명이라 믿은 잘못된 상대","original":"False Soulmate","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"깊이 사랑하고 운명적인 상대라고 믿었지만 서로의 관계가 지속될 수 없거나 기대했던 모습과 다름을 깨닫는 관계다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-009547/index.html"},{"id":"MEJE-KW-009548","row_version":1,"title":"틀니를 이용한 웃음","original":"False Teeth Tomfoolery","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 틀니가 빠지거나 튀어나오는 장면을 우스꽝스러운 사건으로 사용하는 재현 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-009548/index.html"},{"id":"MEJE-KW-009549","row_version":2,"title":"겉만 낙원인 세계","original":"False Utopia","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"모든 것이 완벽한 곳으로 소개되지만 내부에는 주민에게 숨겨진 불평등이나 위험이 존재하는 사회 설정이다. 겉모습만으로 현실을 다르게 보이게 하는 장소 설정은 가짜 마을과 맞닿는다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-009549/index.html"},{"id":"MEJE-KW-009550","row_version":1,"title":"과부인 척하는 인물","original":"False Widow","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"배우자가 살아 있거나 혼인 상태가 다름에도 과부라고 주장해 사회적 위치나 주변의 반응을 바꾸는 인물이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-009550/index.html"},{"id":"MEJE-KW-009551","row_version":2,"title":"이야기로 전해지는 영웅","original":"Famed in Story","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물의 업적이 노래나 전설로 전해지며 이야기 세계 안에서 명성을 얻게 된다. 이야기 속 명성이 게임 진행 조건으로 바뀌면 명성으로 열리는 진행처럼 구현될 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-009551/index.html"},{"id":"MEJE-KW-009552","row_version":1,"title":"명성으로 열리는 진행","original":"Fame Gate","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 플레이어의 명성이나 악명이 일정 수준에 도달해야 주요 임무나 장소가 열리는 진행 규칙이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-009552/index.html"},{"id":"MEJE-KW-009553","row_version":1,"title":"악명으로 얻는 유명세","original":"Fame Through Infamy","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"인물이 좋은 평가 대신 해로운 행동으로 사람들의 주목을 얻으려는 동기나 상황이다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-009553/index.html"},{"id":"MEJE-KW-009554","row_version":2,"title":"가족의 몸을 빼앗는 존재","original":"Familial Body Snatcher","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"자신의 가족이나 후손의 몸을 차지하며 생존이나 권력을 이어 가는 초자연적 존재다. 가계의 여러 세대가 한 적과 얽힌다는 점에서 대를 이어 맞서는 적과 이어진다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-009554/index.html"},{"id":"MEJE-KW-009555","row_version":1,"title":"가족을 먹었다는 폭로","original":"Familial Cannibalism Surprise","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 뒤늦게 가족의 유해가 자신에게 음식으로 제공되었다는 사실을 알게 되는 잔혹한 반전이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-009555/index.html"},{"id":"MEJE-KW-009556","row_version":2,"title":"가족 같은 사이의 다정한 꾸중","original":"Familial Chiding","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"가족이나 가까운 사이의 인물이 상대의 잘못을 엄하게 몰아붙이기보다 친밀감이 묻어나는 말로 바로잡는다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-009556/index.html"},{"id":"MEJE-KW-009557","row_version":1,"title":"유명한 가족의 그림자","original":"Familial Fame Frustrations","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"가족 중 한 사람이 유명해지면서 다른 가족이 사생활 침해, 비교, 주변의 접근 같은 부담을 겪는다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-009557/index.html"},{"id":"MEJE-KW-009558","row_version":2,"title":"대를 이어 맞서는 적","original":"Familial Foe","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"한 적대자가 한 사람을 넘어 그 가족과 후손에게 오랫동안 맞서며 세대를 가로지르는 갈등을 만든다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-009558/index.html"},{"id":"MEJE-KW-009559","row_version":1,"title":"마법적 결속을 맺은 사역 존재","original":"Familiar","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"인물과 마법적 결속을 맺고 곁에서 돕는 존재. 동물·인간형 등 모습이 다양하며 주인이 반드시 마법사일 필요는 없다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-009559/index.html"},{"id":"MEJE-KW-009560","row_version":1,"title":"익숙한 장소의 폐허","original":"Familiar Ruins","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"이전에 잘 알려진 장소가 시간이 흐른 뒤 파괴된 모습으로 다시 등장해 상실과 변화를 드러낸다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-009560/index.html"},{"id":"MEJE-KW-009561","row_version":1,"title":"익숙한 노래의 낯선 언어","original":"Familiar Soundtrack, Foreign Lyrics","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"널리 알려진 노래를 다른 언어의 가사로 다시 불러 친숙한 선율과 낯선 문화적 분위기를 함께 전한다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-009561/index.html"},{"id":"MEJE-KW-009562","row_version":2,"title":"가족이 운영하는 사업","original":"Family Business","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"혈연이나 가족 관계에 있는 인물들이 함께 소유하거나 운영하는 조직으로, 승계와 역할 분담이 이야기 갈등이 되기도 한다. 가족이 함께 운영하는 조직의 역할 갈등은 가족 모임의 파국으로 이어질 수 있다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-009562/index.html"},{"id":"MEJE-KW-009563","row_version":2,"title":"가족 모임의 파국","original":"Family Disunion","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"재회나 결혼식 같은 가족 모임에서 숨겨진 갈등과 비밀이 한꺼번에 드러나 관계가 흔들리는 전개다. 가족 모임에 쌓인 문제가 터지는 전개는 가족 드라마의 한 장면이 된다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-009563/index.html"},{"id":"MEJE-KW-009565","row_version":1,"title":"가족 전체를 겨냥한 제거","original":"Family Extermination","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"한 가족의 구성원들을 한꺼번에 표적으로 삼는 공격이 이야기의 큰 갈등이 된다. 동기는 복수·협박·권력 다툼 등 다양하다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-009565/index.html"},{"id":"MEJE-KW-009566","row_version":3,"title":"눈을 닮은 가족","original":"Family Eye Resemblance","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"가족 구성원에게 같은 모양이나 색의 눈을 부여해 혈연 관계를 대사 없이 암시하는 시각 기호다. 가족사진 속 관계의 단서에도 인물 사이의 혈연을 보여 주는 눈과 자세의 단서가 담길 수 있다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-009566/index.html"},{"id":"MEJE-KW-009567","row_version":1,"title":"아동용으로 순화된 총기","original":"Family-Friendly Firearms","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"어린이용 영상에서 실제 총기 대신 빛이나 장난감 같은 효과의 무기를 보여 폭력 수위를 낮추는 재현 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-009567/index.html"},{"id":"MEJE-KW-009568","row_version":2,"title":"가족용 작품 속 순화된 성숙 소재","original":"Family-Friendly \"Mature\" Content","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"가족 대상 작품 안의 극중 방송·게임·술집·폭력 등 성숙한 소재를 암시나 희화화로 순화해 보여 주는 표현.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-009568/index.html"},{"id":"MEJE-KW-009569","row_version":2,"title":"순화해서 묘사한 스트리퍼","original":"Family-Friendly Stripper","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"스트리퍼를 등장시키면서 노출이나 성적 행동을 제한해 작품의 표현 수위에 맞추는 재현 방식.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-009569/index.html"},{"id":"MEJE-KW-009570","row_version":1,"title":"가문의 명예","original":"Family Honor","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"가족의 평판에 대한 자부심 때문에 자신의 행동이 집안 전체의 명예에 영향을 준다고 여기고 선택을 바꾸는 인물의 동기.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-009570/index.html"},{"id":"MEJE-KW-009571","row_version":3,"title":"가족을 우선하는 남성","original":"Family Man","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"자신이 꾸린 가족과 태어난 가족 모두에 충실하며 그 관계를 행동의 중심에 두는 남성 인물형이다. 가족의 가치를 지키는 악당처럼 가족을 아끼는 마음은 인물의 다른 도덕적 선택과 공존할 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-009571/index.html"},{"id":"MEJE-KW-009573","row_version":1,"title":"중심 인물의 죽음으로 갈라진 가족","original":"Family Pillar Death","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"가족을 이어 주던 사람이 죽자 남은 이들의 애도 방식이 엇갈려 서로의 관계까지 약해지는 전개다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-009573/index.html"},{"id":"MEJE-KW-009574","row_version":1,"title":"가족사진 속 관계의 단서","original":"Family Portrait of Characterization","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"가족사진의 거리와 자세·표정을 통해 가족 사이의 친밀함이나 긴장을 대사 없이 보여 주는 시각 연출이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-009574/index.html"},{"id":"MEJE-KW-009575","row_version":1,"title":"뒤집히는 가족 관계","original":"Family Relationship Switcheroo","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"새 사실이 밝혀지며 부모·형제·친척으로 알고 있던 사람 사이의 관계가 예상과 다르게 다시 정해진다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-009575/index.html"},{"id":"MEJE-KW-009576","row_version":1,"title":"가족 이름의 공통 주제","original":"Family Theme Naming","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"한 집안 구성원의 이름을 같은 뜻이나 소리의 규칙으로 지어 혈연과 공동 정체성을 드러내는 명명 관습이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-009576/index.html"},{"id":"MEJE-KW-009577","row_version":1,"title":"가족 이름을 내건 작품 제목","original":"Family Title","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"주요 인물들의 성이나 가족 이름을 제목에 써 이야기가 그 집안을 중심으로 펼쳐짐을 알리는 명명 방식이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-009577/index.html"},{"id":"MEJE-KW-009578","row_version":2,"title":"가족용 작품의 충격적인 죽음","original":"Family-Unfriendly Death","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"어린이도 볼 것으로 예상된 작품에서 예상보다 강한 죽음의 표현이 나와 관객의 기대와 충돌하는 재현이다. 가족용 작품의 거친 폭력과 함께 가족용 작품에 기대한 표현 수위를 넘어서는 사례다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-009578/index.html"},{"id":"MEJE-KW-009579","row_version":1,"title":"가족용 작품의 거친 폭력","original":"Family-Unfriendly Violence","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"온화한 분위기의 작품에 예상보다 직접적인 폭력이 들어와 관객에게 위협과 불편함을 주는 재현 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-009579/index.html"},{"id":"MEJE-KW-009580","row_version":1,"title":"가족의 가치를 지키는 악당","original":"Family-Values Villain","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"다른 영역에서는 잔혹한 악당이 자기 가족과 전통적인 가정 규범만은 소중히 여기는 인물형이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-009580/index.html"},{"id":"MEJE-KW-009581","row_version":2,"title":"가족과 직업 중 하나를 고르라는 압박","original":"Family Versus Career","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 돌봄과 직업적 성공을 양립할 수 없는 선택으로 그려 특히 어머니에게 한쪽을 포기하도록 요구하는 관습이다. 가족을 우선하는 남성은 가족을 향한 충성을 강조하지만 이 항목에서는 직업과 돌봄이 대립한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-009581/index.html"},{"id":"MEJE-KW-009582","row_version":1,"title":"유명한 조상의 그늘","original":"Famous Ancestor","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 널리 알려진 조상과 닮았다는 기대를 받거나 그 이름으로 자기 능력을 설명받는 인물 설정이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-009582/index.html"},{"id":"MEJE-KW-009583","row_version":2,"title":"실존 두 명 뒤에 끼운 허구 인물","original":"Famous, Famous, Fictional","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"알려진 실존 인물이나 사물을 연달아 든 뒤 허구의 사례를 같은 목록에 넣어 세계의 차이를 자연스럽게 알리는 대사 방식이다. 미래 시대의 과거 문화 애호가은 미래 작품에서 현재 문화의 이름을 자연스럽게 언급할 수 있는 인물형이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-009583/index.html"},{"id":"MEJE-KW-009584","row_version":1,"title":"유명하다는 이유로 유명한 사람","original":"Famous for Being Famous","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"뚜렷한 업적보다 계속되는 관심과 노출 때문에 이름 자체가 유명세를 유지하는 인물형이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-009584/index.html"},{"id":"MEJE-KW-009585","row_version":1,"title":"처음이라는 명성","original":"Famous for Being First","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"어떤 일을 최초로 해낸 인물에게 후속 성취자보다 큰 상징성과 명예를 주는 평가 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-009585/index.html"},{"id":"MEJE-KW-009586","row_version":1,"title":"유명인 이름을 붙인 외국인","original":"Famous-Named Foreigner","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 낯선 나라 출신 인물에게 그 나라의 유명인과 같은 이름을 붙여 국적을 손쉽게 표시하는 작명 관습이다. 실제 작명 문화와는 다를 수 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-009586/index.html"},{"id":"MEJE-KW-009587","row_version":2,"title":"팬","original":"Fan","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"특정 작품이나 사람·활동에 지속적으로 관심을 가지고 감상과 참여를 이어 가는 사람이다. 팬덤은 개별 팬들이 관계를 맺으며 이루는 공동체다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"names/724cc77d2d75c51c/index.html"},{"id":"MEJE-KW-009588","row_version":1,"title":"팬이 다시 짠 감상 순서","original":"Fanachronic Order","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"팬들이 공식 공개 순서보다 다른 순서로 회차를 보는 편이 이야기를 더 잘 이해하거나 즐길 수 있다고 제안하는 관습이다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-009588/index.html"},{"id":"MEJE-KW-009589","row_version":3,"title":"팬이 붙인 대체 제목","original":"Fan Alternate Title","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"작품의 공식 제목과 별도로 팬들이 인상적인 특징이나 유사성을 바탕으로 새 이름을 만들어 부르는 현상이다. 팬이 붙인 별명이 인물이나 사물의 이름을 바꾸는 경우라면 이 항목은 작품 전체의 제목을 바꾼다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-009589/index.html"},{"id":"MEJE-KW-009590","row_version":2,"title":"팬 제작 애니메이션","original":"Fan Animation","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04"],"summary":"팬 창작자가 직접 만든 애니메이션. 기존 작품과 인물을 바탕으로 한 2차 창작일 수도 있고 독자적인 원작일 수도 있다. 팬아트에 움직임과 시간을 더하면 팬 제작 애니메이션으로 이어질 수 있다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"분류축","entry_url":"cards/MEJE-KW-009590/index.html"},{"id":"MEJE-KW-009591","row_version":1,"title":"팬아트","original":"Fan Art","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04"],"summary":"팬이 기존 작품의 인물과 세계를 그림이나 다른 시각 예술로 다시 표현하는 창작 형식이다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"분류축","entry_url":"cards/MEJE-KW-009591/index.html"},{"id":"MEJE-KW-009592","row_version":1,"title":"광신적 불길 이미지","original":"Fanatical Fire","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"종교적 광신이나 극단주의 인물 주변에 불길을 반복해서 배치해 위험한 확신을 시각화하는 상징 관습이다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-009592/index.html"},{"id":"MEJE-KW-009593","row_version":2,"title":"같은 작품의 팬으로 가까워지기","original":"Fan Bonding","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"서로 좋아하는 작품이 같다는 사실을 알게 된 인물들이 그 관심사를 통해 빠르게 친밀해지는 관계 장면이다. 같은 작품을 좋아하는 팬이라는 공통점이 인물 관계를 가깝게 만든다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-009593/index.html"},{"id":"MEJE-KW-009594","row_version":2,"title":"과열된 남성 팬","original":"Fanboy","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"특정 작품이나 인물에 강하게 몰입하거나 과도하게 옹호하는 남성 팬을 가리키는 표현. 지식 과시나 배타적인 태도는 가능한 모습 중 하나다. 팬덤 안의 배타적 행동과 함께 팬 지식을 배타적으로 사용하는 행동을 다룬다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-009594/index.html"},{"id":"MEJE-KW-009595","row_version":2,"title":"팬 공동체의 별명","original":"Fan Community Nicknames","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"팬 집단이 스스로를 부르거나 외부에서 붙인 별명이 공동체의 정체성을 나타내는 언어 관습이다. 팬덤이 자기 이름을 만들거나 받아들이는 과정에서 공동체의 정체성이 드러난다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-009595/index.html"},{"id":"MEJE-KW-009596","row_version":2,"title":"팬 행사","original":"Fan Convention","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"같은 작품이나 분야를 좋아하는 사람들이 모여 창작자와 작품을 만나고 교류하는 공개 모임이다. 팬덤이 온라인 관계를 넘어 한 장소에 모여 교류하는 방식이다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-009596/index.html"},{"id":"MEJE-KW-009597","row_version":3,"title":"팬이 상상한 자녀 캐릭터","original":"Fan-Created Offspring","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"공식 작품에 없는 등장인물의 자녀나 후손을 팬이 만들어 관계와 미래 이야기를 확장하는 2차 창작이다. 팬이 더 바라는 연인 조합으로 지지받는 두 인물의 미래를 상상하며 자녀 캐릭터가 만들어지기도 한다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-009597/index.html"},{"id":"MEJE-KW-009598","row_version":1,"title":"호화로운 야영","original":"Fancy Camping","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"자연 속에서 지내는 야영에 넉넉한 침구와 가구·편의 시설을 들여 사실상 고급 숙박처럼 꾸민 배경이다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-009598/index.html"},{"id":"MEJE-KW-009599","row_version":1,"title":"격식을 갖춘 만찬","original":"Fancy Dinner","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"고급 식당이나 부유한 집에서 정해진 예절과 화려한 상차림으로 진행되는 식사 장면이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-009599/index.html"},{"id":"MEJE-KW-009600","row_version":1,"title":"호화 화장실에 놀라기","original":"Fancy Toilet Awe","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"평범한 설비에 익숙한 인물이 고급 화장실의 낯선 기능과 장식에 감탄하거나 당황하는 장면이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-009600/index.html"},{"id":"MEJE-KW-009601","row_version":2,"title":"팬의 환멸","original":"Fan Disillusionment","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"오래 좋아하던 작품이나 창작자가 기대를 거듭 저버렸다고 느낀 팬이 결국 애정을 접는 변화다. 해답을 싫어하는 팬들이 작품에 대한 오랜 애정을 끊는 한 계기가 될 수 있다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-009601/index.html"},{"id":"MEJE-KW-009602","row_version":1,"title":"해답을 싫어하는 팬들","original":"Fan-Disliked Explanation","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"작품이 큰 수수께끼에 답을 내놓았지만 팬들이 그 설명보다 미해결 상태를 더 낫게 여기며 반발하는 반응이다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-009602/index.html"},{"id":"MEJE-KW-009603","row_version":2,"title":"기대된 성적 장면을 불쾌하게 뒤집기","original":"Fan Disservice","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"성적 볼거리처럼 시작한 장면을 의도적으로 기괴하거나 불편하게 만들어 관객의 기대를 꺾는 연출이다. 관객을 겨냥한 성적 볼거리의 성적 자극을 불쾌감이나 공포로 뒤집는 변주다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-009603/index.html"},{"id":"MEJE-KW-009604","row_version":1,"title":"팬덤","original":"Fandom","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"같은 작품이나 인물을 좋아하는 사람들이 정보와 감상을 나누며 형성한 공동체다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-009604/index.html"},{"id":"MEJE-KW-009605","row_version":2,"title":"팬의 화를 부르는 오해","original":"Fandom-Enraging Misconception","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"작품의 이름이나 설정을 자꾸 잘못 알고 말하는 바깥 사람에게 팬들이 격하게 반응하는 상황이다. 팬덤의 금기 발언이 팬 내부의 다른 의견을 향한 반발이라면 이 항목은 작품을 잘못 아는 말에 대한 반발이다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-009605/index.html"},{"id":"MEJE-KW-009606","row_version":1,"title":"팬덤의 금기 발언","original":"Fandom Heresy","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"팬 집단 안에서 당연하다고 여기는 평가에 반대하는 의견이 공동체의 강한 반발을 부르는 현상이다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-009606/index.html"},{"id":"MEJE-KW-009607","row_version":1,"title":"팬덤의 성장과 쇠퇴","original":"Fandom Life Cycle","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"작품이 알려지며 팬 활동이 커졌다가 시간이 흐르면서 줄거나 다른 형태로 이어지는 공동체의 변화 과정이다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-009607/index.html"},{"id":"MEJE-KW-009608","row_version":2,"title":"팬덤을 향한 작품 속 신호","original":"Fandom Nod","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품이 팬들이 만든 별명이나 농담을 대사와 배경에 넣어 팬 공동체에 알아볼 만한 인사를 보내는 제작 관습이다. 작품이 팬들이 붙인 팬이 붙인 대체 제목을 대사로 언급하면 이 제작상 신호가 된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-009608/index.html"},{"id":"MEJE-KW-009609","row_version":2,"title":"팬덤 사이의 경쟁","original":"Fandom Rivalry","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"서로 다른 작품이나 인물을 좋아하는 팬 집단이 우열을 다투며 상대 집단을 깎아내리는 현상이다. 경쟁하는 팬덤이 서로의 팬을 공격하면 다른 작품의 팬을 미워하기으로 이어질 수 있다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-009609/index.html"},{"id":"MEJE-KW-009610","row_version":2,"title":"특정 팬덤에서 반복되는 줄거리","original":"Fandom-Specific Plot","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"한 작품의 팬 창작물에서 유난히 자주 되풀이되어 그 팬덤만의 익숙한 이야기처럼 굳은 줄거리다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-009610/index.html"},{"id":"MEJE-KW-009611","row_version":1,"title":"팬덤의 유명 인사","original":"Fandom VIP","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"공식 제작진은 아니지만 팬 사이트나 창작물·활동으로 팬 공동체 안에서 널리 알려진 사람이다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-009611/index.html"},{"id":"MEJE-KW-009612","row_version":1,"title":"팬덤 안의 배타적 행동","original":"Fan Dumb","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"일부 팬이 자기 해석과 자격을 강요하며 다른 팬을 공격해 공동체의 대화를 어렵게 만드는 행동이다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-009612/index.html"},{"id":"MEJE-KW-009613","row_version":1,"title":"팬이 다시 편집한 작품","original":"Fan Edit","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"팬이 기존 영상이나 소리를 재배열해 장면의 순서와 리듬을 바꾼 비공식 편집물이다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-009613/index.html"},{"id":"MEJE-KW-009614","row_version":1,"title":"팡파르","original":"Fanfare","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"금관악기의 힘찬 소리로 인물의 등장이나 승리·축하의 순간을 알리는 짧은 음악 형식이다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-009614/index.html"},{"id":"MEJE-KW-009615","row_version":2,"title":"팬픽을 부르는 빈틈","original":"Fanfic Fuel","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"공식 작품에서 설명하지 않은 과거나 사건 사이의 공백이 팬들에게 새로운 이야기를 쓸 여지를 주는 상태다. 팬픽에 자주 쓰이는 조연은 공식 작품의 빈틈이 팬픽의 인물 선택에도 영향을 주는 경우다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-009615/index.html"},{"id":"MEJE-KW-009616","row_version":2,"title":"팬픽에 자주 쓰이는 조연","original":"Fanfic Magnet","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"공식 작품에서 잠깐 등장하고 사라져 후속 설정의 제약이 적은 인물이 팬 창작의 주인공으로 자주 선택되는 현상이다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-009616/index.html"},{"id":"MEJE-KW-009617","row_version":2,"title":"팬 제작 영화","original":"Fan Film","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04"],"summary":"팬이 기존 작품의 인물이나 세계를 바탕으로 새 영상을 직접 촬영해 만든 비공식 영화 형식이다. 팬 제작 애니메이션은 팬 제작 영화가 애니메이션 형식으로 만들어진 경우다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"분류축","entry_url":"cards/MEJE-KW-009617/index.html"},{"id":"MEJE-KW-009618","row_version":1,"title":"팬을 치켜세우는 작품","original":"Fan Flattering","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품이 자기 팬을 다른 사람보다 특별하거나 우월하다고 말해 관객의 소속감에 호소하는 제작 관습이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-009618/index.html"},{"id":"MEJE-KW-009619","row_version":3,"title":"팬 제작 게임","original":"Fan Game","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04"],"summary":"팬이 기존 작품을 바탕으로 게임을 새로 만들어 세계와 캐릭터를 플레이할 수 있게 한 비공식 창작물이다. 팬 제작 리메이크는 팬 게임 가운데 기존 게임 자체를 다시 만드는 형식이다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"분류축","entry_url":"cards/MEJE-KW-009619/index.html"},{"id":"MEJE-KW-009620","row_version":3,"title":"여성 팬","original":"Fangirl","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이나 인물을 좋아하고 참여하는 여성 팬을 가리키는 표현. 작품 속에서는 특정 남성 캐릭터에 집착한다는 과장된 고정관념으로 그려지기도 한다. 과열된 남성 팬처럼 성별을 가리키는 팬 명칭에 특정한 행동 고정관념이 붙는 경우를 다룬다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-009620/index.html"},{"id":"MEJE-KW-009621","row_version":2,"title":"송곳니로 표시되는 악역","original":"Fangs Are Evil","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"날카로운 송곳니를 위험하거나 사악한 존재를 빠르게 알아보게 하는 외형 신호로 사용하는 관습이다. 송곳니 때문에 달라지는 발음은 송곳니를 외형뿐 아니라 목소리의 특징으로까지 이어 붙이는 표현이다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-009621/index.html"}]}.cards;